@startuml

class City {
  + Name : string
  + Inhabitants : int
}

class Attraction {
  + Name : string
  + Address : string
}

class GuidedTour {
  + Duration : string
  + NumberOfVisitors : int
}

class Person {
  + Name : string
}

class Visitor extends Person {}

class Guide extends Person {}

class Discount {
  + Amount : float
}

City "1" -- "*" Attraction
Attraction "1" -- "*" GuidedTour
GuidedTour "*" -- "1" Guide
GuidedTour "1" -- "0..20" Visitor
GuidedTour "1" -- "0..*" Discount
Discount "0..*" -- "1" Visitor

@enduml

